local HerbGardener = {}
local PRODUCTS = {
    rosemary = { name = "Rožmarin", herbSeedCost = 1, waterCost = 1, time = 2, cost = 14, flavorStrength = 30, description = "Rožmarin za kulinariko in zdravilstvo." },
    sage = { name = "Žajbelj", herbSeedCost = 1, waterCost = 1, time = 3, cost = 22, flavorStrength = 45, prestige = 1, description = "Žajbelj za kulinariko." },
    thyme = { name = "Timijan", herbSeedCost = 1, waterCost = 1, time = 3, cost = 28, flavorStrength = 50, prestige = 2, description = "Timijan za fine jedi." },
    lavender = { name = "Sivka", lavenderSeedCost = 1, waterCost = 1, time = 5, cost = 60, flavorStrength = 65, prestige = 4, happiness = 1, description = "Sivka za parfume in pomirjanje." },
    silver_petal_herb = { name = "Srebrno cvetlična zelišča", lavenderSeedCost = 1, silverCost = 1, waterCost = 1, time = 8, cost = 140, flavorStrength = 85, prestige = 10, happiness = 2, description = "Zelišča iz srebrno cvetočih rastlin za plemiče." },
    royal_grand_herb = { name = "Kraljevski veliki zelišča", lavenderSeedCost = 1, herbSeedCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, waterCost = 2, time = 13, cost = 700, flavorStrength = 100, prestige = 30, happiness = 7, description = "Velika kraljevska zelišča z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Zeliščarska postaja", cost = { gold = 220, wood = 120, stone = 100 }, upkeep = 5, qualityBonus = 5 },
    herb_garden = { name = "Zeliščni vrt", cost = { gold = 800, wood = 220, stone = 250, water = 10 }, upkeep = 20, qualityBonus = 18 },
    drying_room = { name = "Sušilnica", cost = { gold = 2000, wood = 350, stone = 600, silver = 25, wood2 = 8 }, upkeep = 50, qualityBonus = 30 },
    royal_herb_atelier = { name = "Kraljevski atelje zelišč", cost = { gold = 8200, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 165, qualityBonus = 55, prestigeBonus = 40 },
}
HerbGardener.herbSeedStock = 24; HerbGardener.lavenderSeedStock = 16; HerbGardener.waterStock = 18; HerbGardener.silverStock = 8; HerbGardener.goldStock = 6; HerbGardener.jewelStock = 6
HerbGardener.productStock = {}; HerbGardener.buildings = {}; HerbGardener.maker = nil; HerbGardener.activeMaking = {}; HerbGardener.totalProducts = 0; HerbGardener.dayTimer = 0
function HerbGardener.init() HerbGardener.herbSeedStock=24; HerbGardener.lavenderSeedStock=16; HerbGardener.waterStock=18; HerbGardener.silverStock=8; HerbGardener.goldStock=6; HerbGardener.jewelStock=6; HerbGardener.productStock={}; HerbGardener.buildings={}; HerbGardener.maker=nil; HerbGardener.activeMaking={}; HerbGardener.totalProducts=0; HerbGardener.dayTimer=0; print("[HerbGardener] Royal Herb Gardener System initialized (6 products, 4 buildings)") end
function HerbGardener.hireMaker(n,s) s=s or math.random(45,85); local c=460+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HerbGardener.maker={name=n or ("Zeliščar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zeliščar najet: %s (spretnost: %d)",HerbGardener.maker.name,s),"success") end; return true end
function HerbGardener.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HerbGardener.build(id) local ok,e=HerbGardener.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HerbGardener.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HerbGardener.getQualityBonus() local b=0; for _,bd in ipairs(HerbGardener.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HerbGardener.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.herbSeedCost and HerbGardener.herbSeedStock<(d.herbSeedCost or 0) then return false,"Premalo zeliščnih semen" end; if d.lavenderSeedCost and HerbGardener.lavenderSeedStock<(d.lavenderSeedCost or 0) then return false,"Premalo sivkinih semen" end; if d.waterCost and HerbGardener.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.silverCost and HerbGardener.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HerbGardener.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HerbGardener.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #HerbGardener.buildings==0 then return false,"Potrebna delavnica" end; if not HerbGardener.maker then return false,"Potreben zeliščar" end; return true end
function HerbGardener.make(pt,qty) qty=qty or 5; local ok,e=HerbGardener.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.herbSeedCost then HerbGardener.herbSeedStock=HerbGardener.herbSeedStock-d.herbSeedCost*qty end; if d.lavenderSeedCost then HerbGardener.lavenderSeedStock=HerbGardener.lavenderSeedStock-d.lavenderSeedCost*qty end; if d.waterCost then HerbGardener.waterStock=HerbGardener.waterStock-d.waterCost*qty end; if d.silverCost then HerbGardener.silverStock=HerbGardener.silverStock-d.silverCost*qty end; if d.goldCost then HerbGardener.goldStock=HerbGardener.goldStock-d.goldCost*qty end; if d.jewelCost then HerbGardener.jewelStock=HerbGardener.jewelStock-d.jewelCost*qty end; local t=d.time; if HerbGardener.maker then t=math.max(1,t-math.floor(HerbGardener.maker.skill/12)) end; table.insert(HerbGardener.activeMaking,{id="herb_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,flavorStrength=d.flavorStrength or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HerbGardener.completeMaking(m) local q=1.0+(HerbGardener.getQualityBonus()/100); if HerbGardener.maker then q=q+(HerbGardener.maker.skill/180) end; q=math.min(2.0,q); HerbGardener.productStock[m.productType]=(HerbGardener.productStock[m.productType] or 0)+m.quantity; HerbGardener.totalProducts=HerbGardener.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HerbGardener.maker then HerbGardener.maker.itemsMade=HerbGardener.maker.itemsMade+m.quantity; if math.random()<0.20 then HerbGardener.maker.skill=math.min(100,HerbGardener.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zelišča pridelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"herb.completed",{productName=m.productName,flavorStrength=m.flavorStrength,happiness=m.happiness}) end end
function HerbGardener.update(dt) if not _G.state then return end; HerbGardener.dayTimer=HerbGardener.dayTimer+dt; if HerbGardener.dayTimer>=30 then HerbGardener.dayTimer=0; for i=#HerbGardener.activeMaking,1,-1 do local m=HerbGardener.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HerbGardener.completeMaking(m); table.remove(HerbGardener.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HerbGardener.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HerbGardener.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HerbGardener.getStats() return {herbSeedStock=HerbGardener.herbSeedStock,lavenderSeedStock=HerbGardener.lavenderSeedStock,waterStock=HerbGardener.waterStock,silverStock=HerbGardener.silverStock,goldStock=HerbGardener.goldStock,jewelStock=HerbGardener.jewelStock,productStock=HerbGardener.productStock,numBuildings=#HerbGardener.buildings,hasMaker=HerbGardener.maker~=nil,makerName=HerbGardener.maker and HerbGardener.maker.name or "—",makerSkill=HerbGardener.maker and HerbGardener.maker.skill or 0,activeMaking=#HerbGardener.activeMaking,totalProducts=HerbGardener.totalProducts} end
return HerbGardener
